import { useState } from 'react';
import { DatePicker } from '@design-schema/react';

function Example() {
  const [open, setOpen] = useState(true ?? true);
  return (
    <DatePicker
      label="Due date"
      name="due"
      defaultValue="2026-09-10"
      open={open}
      onOpenChange={(next) => {
        setOpen(next);
        undefined?.(next);
      }}
    />
  );
}

<Example />

